    except ResourceNotFoundError as e:
        # Erro de negócio — Claude pode tentar alternativa
        return {
            "type": "tool_result",
            "tool_use_id": tool_call_id,
            "is_error": True,
            "content": f"Não encontrado: {str(e)}. Tente buscar por nome."
        }
